using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;
namespace RebirthEntityStudio {
 public sealed class RebirthBodyHeadAssembly:IDisposable {
  public BodyHeadConnection connection;public FaceRecipe face;public FaceTemplate template;public Material sourceMaterial,skin,eyes;public Material[] oral,hairMaterials;public Mesh hair;public FacialHairResult facial;
  public static TextAsset Settings(BodyRecipe recipe){var asset=AssetDatabase.LoadAssetAtPath<TextAsset>(AssetDatabase.GUIDToAssetPath(recipe.attachedHeadSettingsGuid));if(asset==null)throw new FileNotFoundException("Attached head settings are missing; choose a saved generated head or remove the attachment");return asset;}
  public static void ValidateSource(TextAsset settings){if(settings==null)throw new ArgumentException("Choose saved generated head settings");var face=JsonUtility.FromJson<FaceRecipe>(settings.text);face.Validate(RebirthFaceGeneratorWindow.ReadTemplate());if(string.IsNullOrEmpty(face.generatedMaterialGuid)&&!face.skin.foundation)throw new InvalidDataException("The attached head needs generated or foundation skin");if(!string.IsNullOrEmpty(face.generatedMaterialGuid)&&AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(face.generatedMaterialGuid))==null)throw new FileNotFoundException("Attached head skin material is missing");}
  public static RebirthBodyHeadAssembly Build(Mesh body,BodyRecipe recipe,bool appearance=true){
   var result=new RebirthBodyHeadAssembly();Mesh raw=null;try{
    var settings=Settings(recipe);ValidateSource(settings);result.template=RebirthFaceGeneratorWindow.ReadTemplate();result.face=JsonUtility.FromJson<FaceRecipe>(settings.text);result.face.Validate(result.template);RebirthFaceBlood.FollowBody(result.face,recipe.damage);raw=RebirthFaceGeneratorModel.Build(result.template,result.face);result.connection=RebirthBodyHeadConnection.Build(body,raw,recipe.height,recipe.attachedHeadSize,recipe.neckJoinHeight,recipe.neckShortening,string.IsNullOrEmpty(recipe.authoredBodyGuid)?RebirthHeadOwnership.Body(body.vertexCount):RebirthAuthoredBody.Ownership(recipe,body.vertexCount),RebirthHeadOwnership.Head(result.template,result.face.resolution,raw.vertexCount));
    result.sourceMaterial=string.IsNullOrEmpty(result.face.generatedMaterialGuid)?null:AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(result.face.generatedMaterialGuid));
    if(appearance){result.skin=result.sourceMaterial!=null?new Material(result.sourceMaterial):new Material(Shader.Find("Standard"));if(result.sourceMaterial==null)RebirthFaceAppearance.FoundationSkin(result.skin,result.face.skin);else{result.skin.SetFloat("_BumpScale",result.face.poreDetail);result.skin.SetFloat("_GlossMapScale",result.face.skinSmoothness/(65f/255f));}RebirthFaceAppearance.ApplySkin(result.skin,result.face);result.skin.color*=recipe.skinTint;result.eyes=RebirthFaceAppearance.EyeMaterial(result.face);result.oral=RebirthFaceGeneratorWindow.CreateOralMaterials(result.face);if(RebirthHairGenerator.HasHair(result.face)){result.hair=RebirthHairGenerator.Build(raw,result.face.hair,result.template,result.face);result.hairMaterials=RebirthHairGenerator.Materials(result.face.hair,result.face);}if(result.face.nativeAppearance.enabled)result.facial=RebirthNativeAppearanceLibrary.Facial(raw,result.face.nativeAppearance);}
    return result;
   }catch{result.Dispose();throw;}finally{if(raw!=null)UnityEngine.Object.DestroyImmediate(raw);}
  }
  public void Draw(PreviewRenderUtility preview){var matrix=connection.headTransform;RebirthNativePreviewLighting.Draw(preview,connection.head,matrix,skin,0);RebirthNativePreviewLighting.Draw(preview,connection.head,matrix,eyes,1);for(int i=2;i<connection.head.subMeshCount;i++)RebirthNativePreviewLighting.Draw(preview,connection.head,matrix,oral[i-2],i);if(hair!=null&&hairMaterials!=null)for(int i=0;i<hairMaterials.Length;i++)RebirthNativePreviewLighting.Draw(preview,hair,matrix,hairMaterials[i],i);if(facial?.mesh!=null)for(int i=0;i<facial.materials.Length;i++)RebirthNativePreviewLighting.Draw(preview,facial.mesh,matrix,facial.materials[i],i);}
  public void ExportInto(GameObject bodyRoot,Material bodyMaterial,BodyRecipe saved,string folder){
   string path=folder+"/AttachedHead.prefab";RebirthFaceGeneratorWindow.Export(template,face,path,sourceMaterial);string headFolder=folder+"/AttachedHead_Assets";var exported=AssetDatabase.LoadAssetAtPath<GameObject>(path);var instance=(GameObject)PrefabUtility.InstantiatePrefab(exported);try{
    PrefabUtility.UnpackPrefabInstance(instance,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);var clipped=UnityEngine.Object.Instantiate(connection.head);clipped.name="Attached head with neck boundary";AssetDatabase.CreateAsset(clipped,folder+"/AttachedHeadMesh.asset");instance.GetComponent<MeshFilter>().sharedMesh=clipped;var renderer=instance.GetComponent<MeshRenderer>();var materials=renderer.sharedMaterials;var skin=new Material(materials[0]){name="Attached head render skin",hideFlags=HideFlags.None};skin.color*=saved.skinTint;AssetDatabase.CreateAsset(skin,folder+"/AttachedHeadRender.mat");materials[0]=skin;renderer.sharedMaterials=materials;RebirthBodyHeadConnection.BindNeck(bodyMaterial,skin,connection.body,face.skinSmoothness);instance.name="Authored head";instance.transform.SetParent(bodyRoot.transform,false);instance.transform.localPosition=connection.translation;instance.transform.localRotation=Quaternion.identity;instance.transform.localScale=Vector3.one*connection.scale;saved.attachedHeadSettingsGuid=AssetDatabase.AssetPathToGUID(headFolder+"/FaceSettings.json");instance=null;
   }finally{if(instance!=null)UnityEngine.Object.DestroyImmediate(instance);}
  }
  public void Dispose(){connection?.Dispose();connection=null;if(hair!=null)UnityEngine.Object.DestroyImmediate(hair);hair=null;foreach(var material in new[]{skin,eyes})if(material!=null)UnityEngine.Object.DestroyImmediate(material);if(oral!=null)foreach(var material in oral)if(material!=null)UnityEngine.Object.DestroyImmediate(material);if(hairMaterials!=null)foreach(var material in hairMaterials)if(material!=null)UnityEngine.Object.DestroyImmediate(material);facial?.Dispose();facial=null;skin=null;eyes=null;oral=null;hairMaterials=null;}
 }
}

